int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int bytes_received = 0;
    struct sk_buff *skb;
    unsigned int copied;

    if (!sock || !m) {
        return -EINVAL;
    }

    lock_sock(sock->sk);

    if (sock->sk->sk_state == TCP_LISTEN) {
        release_sock(sock->sk);
        return -EINVAL;
    }

    while ((skb = skb_dequeue(sock->sk->sk_receive_queue)) == NULL) {
        if (sock->sk->sk_err || (flags & MSG_DONTWAIT)) {
            release_sock(sock->sk);
            return -EAGAIN;
        }

        wait_for_tcp_receive(sock->sk);
    }

    copied = skb->len;
    if (buf_len < copied) {
        copied = buf_len;
    }

    memcpy(m->msg_iobuf, skb->data, copied);
    m->msg_flags = 0;

    if (skb->pkt_type == PACKET_OTHERHOST || skb->pkt_type == PACKET_MULTICAST) {
        m->msg_flags |= MSG_TRUNC;
    }

    if (skb->ip_summed == CHECKSUM_NONE) {
        m->msg_flags |= MSG_CTRUNC;
    }

    bytes_received = copied;
    kfree_skb(skb);

    sock->sk->sk_data_processed += copied;
    release_sock(sock->sk);

    return bytes_received;
}

int receive_socket_message(struct kiocb *iocb, struct socket *sock,
                           struct msghdr *m, size_t buf_len, int flags)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    size_t copied = 0;
    long timeo;

    if (!sock || !m || !buf_len)
        return -EINVAL;

    lock_sock(sk);

    if (sk->sk_state == TCP_LISTEN) {
        release_sock(sk);
        return -EINVAL;
    }

    timeo = sock_rcvtimeo(sk, flags & MSG_DONTWAIT);

    while (1) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb)
            break;

        if (!timeo) {
            release_sock(sk);
            return -EAGAIN;
        }

        ret = wait_for_rx_intr(sk, timeo);
        if (ret)
            break;

        timeo = sock_rcvtimeo(sk, flags & MSG_DONTWAIT);
    }

    if (!skb) {
        release_sock(sk);
        return ret;
    }

    if (skb->len > buf_len) {
        m->msg_flags |= MSG_TRUNC;
        copied = buf_len;
    } else {
        copied = skb->len;
    }

    memcpy(m->msg_name, skb->cb, sockaddr_size);
    m->msg_namelen = sockaddr_size;

    if (skb_copy_datagram_const(m->msg_iov, 0, skb->data, copied, flags)) {
        kfree_skb(skb);
        release_sock(sk);
        return -EFAULT;
    }

    skb_consume(skb, copied);
    skb_queue_head(&sk->sk_receive_queue, skb);

    sk->sk_state = TCP_ESTABLISHED;

    release_sock(sk);
    return copied;
}

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                                size_t buf_len, int flags) {
    int result;
    size_t copied;
    struct sk_buff *skb;
    struct sock *sk = sock->sk;
    struct sockaddr *addr;

    if (!sock || !m || !buf_len) {
        return -EINVAL;
    }

    if (sk->sk_state == TCP_LISTEN) {
        return -EOPNOTSUPP;
    }

    sock_lock(sk);
    if (sk->sk_shutdown & RCV_SHUTDOWN) {
        sock_unlock(sk);
        return -ECONNRESET;
    }

    if (skb_queue_empty(&sk->sk_receive_queue)) {
        result = wait_for_data_on_socket(sk, flags);
        if (result < 0) {
            sock_unlock(sk);
            return result;
        }
    }

    skb = skb_peek(&sk->sk_receive_queue);
    if (!skb) {
        sock_unlock(sk);
        return -EAGAIN;
    }

    result = skb->len;
    if (result > buf_len) {
        result = -EMSGSIZE;
    } else {
        copied = skb_copy_datagram_msg(skb, 0, m, result);
        if (copied < 0) {
            sock_unlock(sk);
            return copied;
        }

        m->msg_flags = skb->pkt_type;

        if (skb->sk && skb->sk->sk_socket) {
            sock = skb->sk->sk_socket;
            addr = (struct sockaddr *)&sock->addr;
            m->msg_name = addr;
            m->msg_namelen = sock->addr_len;
        }
    }

    skb_unlink(skb, &sk->sk_receive_queue);
    sock_wfree(sk, skb);
    sock_unlock(sk);

    return result < 0 ? result : (int)result;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int bytes_received = 0;
    struct sk_buff *skb;
    struct sock *sk = sock->sk;
    int copied;

    if (!sock || !m || buf_len == 0)
        return -EINVAL;

    lock_sock(sk);

    while (1) {
        if (sk->sk_state == SS_DISCONNECTED) {
            release_sock(sk);
            return -ENOTCONN;
        }

        skb = skb_peek(&sk->sk_receive_queue);
        if (!skb) {
            if (flags & MSG_DONTWAIT) {
                release_sock(sk);
                return -EAGAIN;
            }

            if (wait_for_more_packets(sk)) {
                release_sock(sk);
                return -ETIMEDOUT;
            }
            continue;
        }

        copied = skb->len;
        if (copied > buf_len)
            copied = buf_len;

        if (skb_copy_datagram_msg(skb, 0, m, copied) < 0) {
            bytes_received = -EFAULT;
            break;
        }

        bytes_received = copied;

        if (skb->skb_iocb && skb->skb_iocb->iocb == iocb)
            iocb->ki_pos += copied;

        skb_pull(skb, copied);
        if (skb->len == 0)
            __skb_unlink(skb, &sk->sk_receive_queue);
        else
            skb = NULL;

        break;
    }

    release_sock(sk);
    return bytes_received;
}

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;

    if (!sock->file) {
        return -EINVAL;
    }

    lock_sock(sk);

    if (sk->sk_state == TCP_CLOSE) {
        release_sock(sk);
        return -ENOTCONN;
    }

    while (1) {
        struct sk_buff *skb;

        skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb) {
            if (flags & MSG_PEEK) {
                copied = skb->len;
                if (copied > buf_len)
                    copied = buf_len;
                if (copied > 0) {
                    err = skb_copy_datagram_const_msg(m, 0, skb, 0, copied);
                    if (err)
                        break;
                }
            } else {
                copied = skb->len;
                if (copied > buf_len)
                    copied = buf_len;
                if (copied > 0) {
                    err = skb_copy_datagram_msg(skb, 0, m, 0, copied);
                    if (err)
                        break;
                    skb_trim(skb, 0);
                    if (!skb->len)
                        kfree_skb(skb);
                    else
                        skb_queue_head(&sk->sk_receive_queue, skb);
                } else {
                    kfree_skb(skb);
                }
            }
            break;
        }

        if (signal_pending(current)) {
            err = -ERESTARTSYS;
            break;
        }

        if (sk->sk_err || (flags & MSG_OOB) || sk->sk_shutdown & RCV_SHUTDOWN) {
            if (sk->sk_shutdown & RCV_SHUTDOWN)
                err = 0;
            else
                err = sock_error(sk);
            if (!err)
                err = -ENOTCONN;
            break;
        }

        if (sk->sk_state != TCP_ESTABLISHED) {
            release_sock(sk);
            sock_put(sk);
            return -ENOTCONN;
        }

        sk_wait_event(sk, &err, 0);
    }

    release_sock(sk);
    return copied ? copied : err;
}
